/* Tray-first UI. This renderer uses the same in-memory demo session as app.js. */
(() => {
  'use strict';
  window.renderMiniUI = ({state:s, icon, button, esc, maskAccount, connectionNames, switchRow, events}) => {
    const viewNames = {home:'SCAU Link',account:'账号与登录',network:'当前网卡',preferences:'偏好设置',logs:'最近记录',about:'关于'};
    const menuItem = (label, action, glyph, extra='') => `<button class="mini-menu-item ${extra}" type="button" data-action="${action}">${icon(glyph)}<span>${label}</span>${icon('chevron-right','menu-chevron')}</button>`;
    const menu = () => `<nav class="mini-more" aria-label="更多选项" ${s.miniMenu?'':'hidden'}>${menuItem('账号与登录','go-account','user-round')}${menuItem('偏好设置','go-preferences','settings-2')}${menuItem('最近记录','go-logs','list')}<div class="mini-menu-rule"></div>${menuItem('打开完整窗口','mini-full','panel-top')}${menuItem('关于 SCAU Link','go-about','info')}<div class="mini-menu-rule"></div>${menuItem('退出应用…','exit','power','exit-item')}</nav>`;
    const row = (label, value) => `<div class="mini-detail-row"><span>${label}</span><span>${value}</span></div>`;
    const details = () => {
      const online=s.connection==='online', recovering=s.connection==='recovering';
      if(recovering) return `<div class="mini-recovery-events"><p class="mini-section-label">本次恢复</p><div>${icon('check')}检测到认证核心异常退出</div><div>${icon('check')}认证核心已重新启动</div><div class="current">${icon('loader-circle','spin')}准备第 2 次重新认证</div></div><button class="mini-inline-link" data-action="go-logs">查看最近记录 ${icon('arrow-up-right')}</button>`;
      return `<ul class="mini-health"><li>${icon(s.connection==='unplugged'?'circle-alert':'circle-check')}<span>${s.connection==='unplugged'?'等待网线接入':'网线已接入'}</span></li><li class="${online?'':'pending'}">${icon(online?'circle-check':'clock-3')}<span>${online?'校园网认证有效':s.connection==='rejected'?'认证未通过':'等待校园网认证'}</span></li><li class="${online?'':'pending'}">${icon(online?'circle-check':'clock-3')}<span>${online?'互联网可访问':'认证后检查互联网'}</span></li></ul><div class="mini-detail-table">${row('校园网账号',esc(maskAccount(s.username)))}<button class="mini-detail-row mini-row-button" data-action="go-network"><span>认证网卡</span><span>以太网 ${icon('chevron-right')}</span></button>${row('自动恢复',s.settings.recovery?'已开启':'已暂停')}</div>`;
    };
    function home() {
      const variants = {
        online:{title:'已连接',subtitle:'校园网可用',glyph:'network',tone:'online',meta:'已在线 2 小时 36 分',metaGlyph:'clock-3',action:button('断开连接','disconnect','mini-primary','log-out')},
        offline:{title:'未连接',subtitle:'准备好连接校园网',glyph:'plug-zap',tone:'offline',meta:'以太网已就绪',metaGlyph:'ethernet-port',action:button('连接校园网','mini-connect','primary mini-primary','arrow-right')},
        connecting:{title:'正在连接',subtitle:'正在核对校园网账号…',glyph:'loader-circle',tone:'connecting',meta:'认证完成后检查网络',metaGlyph:'shield-check',action:button('取消连接','cancel','mini-primary','x')},
        recovering:{title:'正在恢复连接',subtitle:'连接异常，正在自动重连',glyph:'refresh-cw',tone:'recovering',meta:'会话已保留，无需重新输入',metaGlyph:'shield-check',action:button('停止重连','cancel','mini-primary','pause')},
        rejected:{title:'需要检查账号',subtitle:'校园网未接受本次认证',glyph:'circle-alert',tone:'rejected',meta:'自动重试已停止',metaGlyph:'pause',action:button('检查账号与密码','go-account','primary mini-primary','user-round')},
        unplugged:{title:'等待网线接入',subtitle:'接入后会继续连接',glyph:'cable',tone:'recovering',meta:'请检查网线或墙上的接口',metaGlyph:'ethernet-port',action:button('取消等待','cancel','mini-primary','x')}
      };
      const v=variants[s.connection]||variants.offline;
      return `<div class="mini-home ${v.tone}"><div class="mini-status"><span class="mini-status-mark ${s.connection==='connecting'?'is-connecting':''}">${icon(v.glyph)}</span><div><h1>${v.title}</h1><p><span class="mini-status-dot"></span>${v.subtitle}</p></div></div><div class="mini-session">${icon(v.metaGlyph)}<span>${v.meta}</span></div>${s.connection==='connecting'?'<div class="mini-progress" role="progressbar" aria-label="正在认证"><span></span></div>':''}${v.action}<button class="mini-disclosure" type="button" data-action="mini-details" aria-expanded="${s.miniDetails}" aria-controls="mini-connection-details"><span>${s.connection==='recovering'?'恢复进度':'连接详情'}</span>${icon('chevron-down',s.miniDetails?'rotated':'')}</button><section class="mini-details" id="mini-connection-details" aria-label="${s.connection==='recovering'?'恢复进度':'连接详情'}" ${s.miniDetails?'':'hidden'}>${details()}</section></div><footer class="mini-foot">${icon(s.connection==='online'?'shield-check':'info')}<span>${s.connection==='online'?'收起小窗，连接继续保持':s.connection==='recovering'?(s.settings.notifications?'恢复完成后将通知你':'恢复在后台继续，可随时查看'):s.connection==='rejected'?'修改后，由你重新发起连接':s.connection==='connecting'?'收起小窗，认证继续在后台进行':s.connection==='unplugged'?'收起小窗，不影响等待网线接入':'使用学校分配的校园网账号'}</span></footer>`;
    }
    function account() {
      const online=s.connection==='online';
      return `<div class="mini-subview"><p class="mini-intro">${online?'管理下次连接使用的账号。':'填写校园网账号，开始本次连接。'}</p><div class="field ${s.invalid&&!s.draftAccount.trim()?'error':''}"><label for="account-username">校园网账号</label><input id="account-username" autocomplete="off" spellcheck="false" placeholder="请输入校园网账号" value="${esc(s.draftAccount)}" ${s.invalid&&!s.draftAccount.trim()?'aria-invalid="true" aria-describedby="mini-username-error"':''}>${s.invalid&&!s.draftAccount.trim()?'<span id="mini-username-error" class="error-text">请输入校园网账号</span>':''}</div><div class="field ${s.invalid&&!s.draftPassword?'error':''}"><label for="account-password">密码</label><div class="input-wrap"><input id="account-password" type="password" autocomplete="off" placeholder="仅用于本次会话" value="${esc(s.draftPassword)}" ${s.invalid&&!s.draftPassword?'aria-invalid="true" aria-describedby="mini-password-error"':''}><button class="input-icon" type="button" data-action="toggle-account-password" aria-label="显示账号密码">${icon('eye')}</button></div>${s.invalid&&!s.draftPassword?'<span id="mini-password-error" class="error-text">请输入校园网密码</span>':''}</div><details class="mini-options"><summary>登录选项 ${icon('chevron-down')}</summary><label class="mini-checkbox"><input type="checkbox" data-setting="retain" ${s.settings.retain?'checked':''}><span>本次会话保留凭据<small>用于断线恢复；退出应用后清除。</small></span></label></details>${button(online?'保存设置':'连接校园网',online?'save-account':'save-account-connect','primary mini-primary',online?'check':'arrow-right')}<p class="mini-form-note">${icon('lock-keyhole')}${online?'保存后在下次连接时生效':'密码不写入配置或运行记录'}</p></div>`;
    }
    function network() {
      return `<div class="mini-subview"><div class="mini-adapter">${icon('ethernet-port')}<div><strong>以太网</strong><p>Realtek Gaming 2.5GbE<br>Family Controller</p></div></div><div class="mini-detail-table">${row('链路状态',s.connection==='unplugged'?'未接入网线':'网线已接入')}${row('链路速度',s.connection==='unplugged'?'—':'100 Mbps')}${row('认证方式','有线校园网')}</div><details class="mini-options"><summary>网络地址 ${icon('chevron-down')}</summary><div class="mini-detail-table">${row('IPv4','192.0.2.16')}${row('网卡类型','物理以太网')}</div></details>${button('管理网络适配器','mini-full-network','mini-primary','arrow-up-right')}</div>`;
    }
    function preferences() {
      return `<div class="mini-subview mini-preferences"><p class="mini-intro">让客户端在后台照顾好连接。</p>${switchRow('recovery','异常后自动恢复','断线或认证核心退出时重新连接。','shield-check')}${switchRow('notifications','连接状态通知','恢复完成或需要处理时提醒。','bell')}<details class="mini-options"><summary>启动与窗口 ${icon('chevron-down')}</summary>${switchRow('launch','登录 Windows 后启动','启动后驻留通知区域。','power')}${switchRow('minimize','关闭完整窗口时收起','保持当前连接，在托盘继续运行。','panel-top')}</details><p class="mini-form-note">手动断开后，自动恢复会暂停。</p></div>`;
    }
    function logs() {
      return `<div class="mini-subview"><p class="mini-intro">只显示本次会话的最近记录。</p><ol class="mini-event-list">${events.slice(0,4).map(e=>`<li>${icon(e.glyph)}<div><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p><time>${e.time}</time></div></li>`).join('')}</ol><div class="mini-log-actions">${button('导出诊断','export','small','download')}${button('全部记录','mini-full-logs','small text','arrow-up-right')}</div><p class="mini-form-note">导出时隐藏账号与网络地址。</p></div>`;
    }
    function about() {
      return `<div class="mini-subview mini-about"><span class="mini-about-icon">${icon('sprout')}</span><h1>SCAU Link</h1><p>让校园网连接，简单一点。</p><span class="tag">认证核心 0.3.0</span><div class="mini-detail-table">${row('平台','Windows 原生桌面')}${row('开源许可','GPL-3.0')}</div>${button('开源致谢','licenses','mini-primary','file-text')}<p class="mini-form-note">为 SCAU 有线校园网设计<br>非学校官方客户端</p></div>`;
    }
    const renderers={home,account,network,preferences,logs,about};
    const sub=s.miniView!=='home';
    const current=renderers[s.miniView]?s.miniView:'home';
    return `<header class="preview-bar"><div class="preview-brand">${icon('sprout')}SCAU Link <small>托盘优先 · 按需展开</small><span class="preview-badge">CONCEPT 02</span></div><div class="preview-controls"><a class="preview-link" href="overview.html">${icon('panel-top')}设计总览</a><select class="preview-select" aria-label="切换演示状态" id="scenario-select">${Object.entries(connectionNames).map(([key,value])=>`<option value="${key}" ${s.connection===key?'selected':''}>${value}</option>`).join('')}</select><button class="preview-link" data-action="demo-connect">体验连接流程 ${icon('arrow-right')}</button></div></header><main class="mini-desktop" id="mini-desktop" aria-label="托盘小窗交互预览"><div class="mini-desktop-caption" aria-hidden="true"><span>SCAU LINK</span><h2>连接好了，<br>就安心做自己的事。</h2><p>小窗常在托盘，需要时再展开。</p><div class="desktop-key-hint">${icon('sprout')}点击右下角托盘图标，打开或收起</div></div><section class="mini-window ${sub?'is-subview':''}" id="mini-window" aria-label="SCAU Link Mini 小窗" ${s.miniVisible?'':'hidden'}><header class="mini-titlebar">${sub?`<button class="mini-icon-button" data-action="mini-back" aria-label="返回连接状态">${icon('arrow-left')}</button><h2>${viewNames[current]}</h2>`:`<span class="mini-wordmark">${icon('sprout')}SCAU Link <small>Mini</small></span>`}<div class="mini-title-actions"><button class="mini-icon-button ${s.miniMenu?'active':''}" data-action="mini-menu" aria-label="更多选项" aria-expanded="${s.miniMenu}" aria-controls="mini-more-options">${icon('settings-2')}</button><button class="mini-icon-button" data-action="mini-hide" aria-label="收起小窗">${icon('minus')}</button></div></header><div id="mini-more-options">${menu()}</div><div class="mini-content" id="mini-content">${renderers[current]()}</div></section><div class="tray-context" aria-label="托盘右键菜单" ${s.miniContext?'':'hidden'}>${menuItem('打开 Mini 小窗','mini-show','sprout')}${menuItem('打开完整窗口','mini-full','panel-top')}<div class="mini-menu-rule"></div>${menuItem(s.connection==='online'?'断开连接':'连接校园网',s.connection==='online'?'disconnect':'mini-connect',s.connection==='online'?'log-out':'plug-zap')}${menuItem('退出应用…','exit','power','exit-item')}</div><footer class="desktop-taskbar" aria-label="模拟 Windows 通知区域"><span class="taskbar-app-name">${icon('sprout')}SCAU Link</span><div class="taskbar-system">${icon('chevron-down','taskbar-chevron')}<button type="button" class="tray-launcher ${s.miniVisible?'active':''} ${s.connection==='online'?'is-online':''}" data-action="mini-tray" aria-label="${s.miniVisible?'收起':'打开'} SCAU Link 小窗" aria-expanded="${s.miniVisible}" aria-controls="mini-window" title="SCAU Link · ${connectionNames[s.connection]} · 右键查看更多">${icon('sprout')}<span class="tray-presence ${s.connection}"></span></button>${icon('ethernet-port')}<time>12:17<small>2026/11/12</small></time></div></footer></main><footer class="stage-footer"><span>MINI → 连接详情 → 完整窗口</span><span>HTML 交互示意 · 演示数据，不会操作真实网络</span></footer><div id="tray-root"></div><div id="toast-root" aria-live="polite"></div><dialog class="modal" id="modal" aria-labelledby="modal-title"></dialog>`;
  };
})();
